import { render, route } from "rwsdk/router";
import { defineApp } from "rwsdk/worker";
import { drizzle } from "drizzle-orm/d1";
import { count, eq } from "drizzle-orm";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";
import { Home } from "@/app/pages/home";
import { users } from "@/db/schema";

export type AppContext = {};

async function getUsers(request: Request, env: Env): Promise<Response> {
  const url = new URL(request.url);
  const params = url.searchParams;

  const limit = Math.max(0, parseInt(params.get("limit") ?? "10", 10) || 10);
  const offset = Math.max(0, parseInt(params.get("offset") ?? "0", 10) || 0);

  const db = drizzle(env.DB);

  const [rows, totalRows] = await Promise.all([
    db
      .select({ id: users.id, name: users.name, email: users.email })
      .from(users)
      .orderBy(users.id)
      .limit(limit)
      .offset(offset),
    db.select({ total: count() }).from(users),
  ]);

  const total = totalRows[0]?.total ?? 0;

  return Response.json({ users: rows, total, limit, offset }, { status: 200 });
}

async function createUser(request: Request, env: Env): Promise<Response> {
  let body: { name?: string; email?: string };
  try {
    body = await request.json();
  } catch {
    return Response.json(
      { error: "Invalid JSON body" },
      { status: 400 }
    );
  }

  const name = body.name?.trim();
  const email = body.email?.trim();

  if (!name || !email) {
    return Response.json(
      { error: "name and email are required" },
      { status: 400 }
    );
  }

  const db = drizzle(env.DB);

  try {
    const inserted = await db
      .insert(users)
      .values({ name, email })
      .returning({ id: users.id, name: users.name, email: users.email });

    return Response.json(inserted[0], { status: 201 });
  } catch (err: unknown) {
    const message =
      err instanceof Error ? err.message : String(err);
    if (
      message.includes("UNIQUE constraint failed") ||
      message.includes("unique")
    ) {
      return Response.json(
        { error: "A user with that email already exists" },
        { status: 409 }
      );
    }
    throw err;
  }
}

export default defineApp([
  setCommonHeaders(),
  ({ ctx }) => {
    // setup ctx here
    ctx;
  },
  route("/api/users", {
    GET: ({ request, ctx }) => getUsers(request, (ctx as { env: Env }).env),
    POST: ({ request, ctx }) => createUser(request, (ctx as { env: Env }).env),
  }),
  render(Document, [route("/", Home)]),
]);

